Here's a complete example with both the `PriceCalculator` class and modern data-driven MSTest tests:

**Production code — `PriceCalculator.cs`**

```csharp
public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(unitPrice);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);
        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal price, int discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(price);
        if (discountPercent is < 0 or > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));
        return price * (100 - discountPercent) / 100m;
    }
}
```

**Tests — `PriceCalculatorTests.cs`**

```csharp
[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // ── CalculateTotal: DataRow for simple inline values ──

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(10.00, 3, 30.00, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00, DisplayName = "Free item")]
    [DataRow(99.99, 2, 199.98, DisplayName = "Fractional price")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, DisplayName = "Negative price")]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    [TestMethod]
    [DataRow(10.00, 0, DisplayName = "Zero quantity")]
    [DataRow(10.00, -1, DisplayName = "Negative quantity")]
    public void CalculateTotal_InvalidQuantity_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    // ── ApplyDiscount: DynamicData with ValueTuples for complex/decimal data ──

    [TestMethod]
    [DynamicData(nameof(ValidDiscountData))]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)>
        ValidDiscountData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
        (99.99m, 15, 84.9915m),
    ];

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_InvalidDiscount_Throws(decimal price, int discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual(nameof(discountPercent), ex.ParamName);
    }

    public static IEnumerable<(decimal price, int discountPercent)> InvalidDiscountData =>
    [
        (100m, -1),
        (100m, 101),
    ];

    [TestMethod]
    public void ApplyDiscount_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(-10m, 10));
    }
}
```

**Key patterns used:**

| Pattern | Where | Why |
|---|---|---|
| `[DataRow]` | `CalculateTotal` | Simple inline values; note `double` params cast to `decimal` since `DataRow` doesn't support `decimal` literals |
| `[DynamicData]` + ValueTuples | `ApplyDiscount` | Type-safe `decimal` values without casting; cleaner for complex data (MSTest 3.7+) |
| `Assert.ThrowsExactly<T>` | Error cases | Modern replacement for `[ExpectedException]`; allows inspecting `ex.ParamName` |
| `sealed` class | Test class | Performance and design clarity |
| Constructor init | `_calculator` | Enables `readonly`; preferred over `[TestInitialize]` for sync setup |
| `DisplayName` | DataRow | Readable test names in Test Explorer |

For the test project, use `MSTest.Sdk` for the simplest setup:

```xml
<Project Sdk="MSTest.Sdk">
  <PropertyGroup>
    <TargetFramework>net9.0</TargetFramework>
  </PropertyGroup>
</Project>
```
